    steps = [
        f"讀題定位：圈出「{tag}」並標記時間、地點、參與者、制度或資料類型。",
        f"整理證據：把商品流動、商人社群、制度安排與文化使用分層；本題核心是「{reason}」。",
        f"核對正解：選項 {aid}「{answer}」同時符合題幹資料與商貿文化交流的歷史推理。",
        "排除誘答：檢查是否把個案當普遍、把相似當同源，或把交流誤寫成單向取代與全面平等。",
        "結論回查：確認年代、空間、群體與證據限制都已納入，且沒有超出資料能支持的範圍。",
    ]
    return {"id": f"question-social-content-hist-hb-iv-2-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-hist-hb-iv-2"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫商貿網絡、商人社群、信用契約、宗教網絡、翻譯知識、技術生產、城市消費、文化混融、性別移動與多重證據情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-hist-hb-iv-2", "examPatternRefs": refs, "solutionStrategy": "先辨識商貿資料中的商品、制度、移動者與使用者，再比較交流如何被翻譯、改造與地方化，最後以多重證據及資料界線檢查推論。", "solutionSteps": steps}

